'use strict';

// Governance Migration — Single Governance Source of Truth phase.
//
// Real, evidenced need: dogfooding found real projects carrying two
// generations of governance at once — a pre-Phase-15B flat scheme
// (`.juntia/agent-rules.md`, `.juntia/workflows.md`, `.juntia/roles/*.md`,
// generated by a since-removed JS string builder) sitting alongside the
// current Knowledge Layer (`.juntia/governance/`). `init()` has always
// deliberately left the old scheme untouched (see
// test/knowledge-layer.test.js's own "old-scheme files... kept untouched"
// test) — safe, but permanent: nothing ever moved a project off it. This
// module is the real conflict-resolution rule `docs/CLI.md#why-update-isnt-
// built-yet` named as the missing piece for `juntia update` — scoped
// narrowly to this one, real, evidenced migration, not a general
// scaffolded-file sync engine.
//
// The rule, applied per candidate file: if the new-scheme location doesn't
// exist yet, OR exists but is still byte-identical to what `juntia init`
// itself would scaffold there (never hand-edited since), migrating the
// legacy content into it is safe — nothing human-authored is lost, because
// there was nothing human-authored at the new location yet. If the new
// location already differs from the stock template, it has already been
// customized (by a human, or by an earlier partial migration someone then
// edited) — migrating would silently discard that; this reports a conflict
// for a human to resolve directly instead of guessing which content should
// win. Free text is never merged — Juntia does not interpret content, only
// transports it.
//
// `.juntia/workflows.md` (a single flat file) has no reliable mapping onto
// the new per-workflow file structure (each new workflow file requires
// real, distinct sections — Goal/When to use/Roles/Skills/Decisions —
// `workflow-knowledge.js` already depends on structurally) — auto-splitting
// it would require interpreting its content, which this module must not do.
// It is reported as not portable, left untouched; the new
// `.juntia/governance/workflows/*.md` files are scaffolded from Juntia's own
// defaults instead (via the existing `init()`, already called first).
//
// Never deletes or modifies a legacy file. Every migration only ever WRITES
// to the new-scheme location; the legacy file survives, byte-identical,
// whether or not its content was copied forward.

const fs = require('fs');
const path = require('path');

const PACKAGE_ROOT = path.join(__dirname, '..', '..');
const TEMPLATES_DIR = path.join(PACKAGE_ROOT, 'templates', 'governance');

const LEGACY_AGENT_RULES = path.join('.juntia', 'agent-rules.md');
const LEGACY_WORKFLOWS = path.join('.juntia', 'workflows.md');
const LEGACY_ROLES_DIR = path.join('.juntia', 'roles');
const LEGACY_ROLE_FILES = ['product.md', 'architect.md', 'engineer.md', 'qa.md'];

const NEW_AGENT_RULES = path.join('.juntia', 'governance', 'rules', 'agent-rules.md');
const NEW_ROLES_DIR = path.join('.juntia', 'governance', 'roles');

// detectLegacyGovernance(projectRoot) -> { hasAgentRules, hasWorkflows, legacyRoleFiles, any }
// Purely a filesystem check — reads no content, decides nothing about
// safety yet.
function detectLegacyGovernance(projectRoot) {
  const hasAgentRules = fs.existsSync(path.join(projectRoot, LEGACY_AGENT_RULES));
  const hasWorkflows = fs.existsSync(path.join(projectRoot, LEGACY_WORKFLOWS));
  const legacyRoleFiles = LEGACY_ROLE_FILES.filter(
    (f) => fs.existsSync(path.join(projectRoot, LEGACY_ROLES_DIR, f)),
  );
  return {
    hasAgentRules,
    hasWorkflows,
    legacyRoleFiles,
    any: hasAgentRules || hasWorkflows || legacyRoleFiles.length > 0,
  };
}

// A new-scheme file is "safe to overwrite with migrated content" exactly
// when it doesn't exist yet, or exists but is still exactly what `init()`
// would have scaffolded there — never when it has diverged from the stock
// template, regardless of why.
function isSafeToOverwrite(newAbsolutePath, templateAbsolutePath) {
  if (!fs.existsSync(newAbsolutePath)) return true;
  if (!fs.existsSync(templateAbsolutePath)) return false;
  return fs.readFileSync(newAbsolutePath, 'utf8') === fs.readFileSync(templateAbsolutePath, 'utf8');
}

function migrateOneFile(projectRoot, legacyRelativePath, newRelativePath, templateRelativePath, report) {
  const legacyAbsolute = path.join(projectRoot, legacyRelativePath);
  const newAbsolute = path.join(projectRoot, newRelativePath);
  const templateAbsolute = path.join(TEMPLATES_DIR, templateRelativePath);
  const legacyContent = fs.readFileSync(legacyAbsolute, 'utf8');

  // Idempotency: a second `update` run after a real migration finds the
  // new-scheme file no longer matching the stock template (it now holds the
  // migrated legacy content) — that is success, already applied, not a new
  // conflict to report. Checked before the stock-template comparison so
  // this always wins over it.
  if (fs.existsSync(newAbsolute) && fs.readFileSync(newAbsolute, 'utf8') === legacyContent) {
    report.alreadyMigrated.push({ from: legacyRelativePath, to: newRelativePath });
    return;
  }

  if (isSafeToOverwrite(newAbsolute, templateAbsolute)) {
    fs.mkdirSync(path.dirname(newAbsolute), { recursive: true });
    fs.writeFileSync(newAbsolute, legacyContent);
    report.migrated.push({ from: legacyRelativePath, to: newRelativePath });
  } else {
    report.conflicts.push({
      from: legacyRelativePath,
      to: newRelativePath,
      reason: `${newRelativePath} already has content different from both Juntia's own default and ${legacyRelativePath} — resolve manually; ${legacyRelativePath} was left untouched`,
    });
  }
}

// migrateGovernance(projectRoot) -> {
//   any: boolean,           // was there any legacy governance to look at at all
//   migrated: [{ from, to }],       // copied just now
//   alreadyMigrated: [{ from, to }],// a previous `update` run already did this — idempotent, not a conflict
//   conflicts: [{ from, to, reason }],
//   notPortable: [{ from, reason }],
// }
//
// Assumes `init(projectRoot)` has already run (the caller's job — same
// precedent `runIntegrate`/`runRoute` already established: scaffold the
// current defaults first, unconditionally, before doing anything else) so
// every new-scheme path this function checks against a template either
// already holds real content or the stock default, never "doesn't exist
// yet because init was never run."
function migrateGovernance(projectRoot) {
  const detected = detectLegacyGovernance(projectRoot);
  const report = {
    any: detected.any, migrated: [], alreadyMigrated: [], conflicts: [], notPortable: [],
  };
  if (!detected.any) return report;

  if (detected.hasAgentRules) {
    migrateOneFile(
      projectRoot,
      LEGACY_AGENT_RULES,
      NEW_AGENT_RULES,
      path.join('rules', 'agent-rules.md'),
      report,
    );
  }

  for (const roleFile of detected.legacyRoleFiles) {
    migrateOneFile(
      projectRoot,
      path.join(LEGACY_ROLES_DIR, roleFile),
      path.join(NEW_ROLES_DIR, roleFile),
      path.join('roles', roleFile),
      report,
    );
  }

  if (detected.hasWorkflows) {
    report.notPortable.push({
      from: LEGACY_WORKFLOWS,
      reason: 'a single flat workflows file has no reliable mapping onto the new, per-workflow file structure '
        + '(.juntia/governance/workflows/*.md, each with its own real Goal/When to use/Roles/Skills/Decisions '
        + 'sections) without interpreting its content, which Juntia must not do. Left untouched — review it '
        + 'yourself for anything project-specific worth copying into the new workflow files by hand.',
    });
  }

  return report;
}

module.exports = {
  LEGACY_AGENT_RULES,
  LEGACY_WORKFLOWS,
  LEGACY_ROLES_DIR,
  LEGACY_ROLE_FILES,
  NEW_AGENT_RULES,
  NEW_ROLES_DIR,
  detectLegacyGovernance,
  migrateGovernance,
};
